SELECT id, qybh, task_type AS taskType, status, task_name AS taskName, record_count AS recordCount, start_time AS startTime, end_time AS endTime, cost_time AS costTime, creator_id AS creatorId, create_time AS createTime FROM t_drdc_rw_4849 WHERE 1=1
AND qybh = #{qybh}
AND task_type = #{taskType}
ORDER BY create_time DESC
